with filtered_inventory as (select * from inventory where product_id in (6, 10)), inventory_stats as (select store_id, product_id, min(last_restock) as min_last_restock, min(last_restock) as first_last_restock from filtered_inventory group by store_id, product_id) select store_id, product_id, min_last_restock, first_last_restock from inventory_stats order by 4, store_id, product_id limit 1
